before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <string>
#include <string_view>
int main() {
    std::string owner = "forest";
    std::string_view view{owner};
    owner[0] = 'F';
    std::cout << view << "\n";
    view.remove_prefix(1);
    std::cout << view << " " << owner << "\n";
}
```

